const body = $json.body || $json;
const rawJd = body.jd_text || body.raw_jd_text || body.job_description || '';

return [{
  json: {
    request_id: body.request_id || `req-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    job_id: body.job_id || `job-${Date.now()}`,
    raw_jd_text: String(rawJd).trim(),
    shortlist_size: Number(body.shortlist_size || 10),
    weights: {
      match_weight: Number(body.match_weight || 0.7),
      interest_weight: Number(body.interest_weight || 0.3)
    },
    supplied_candidates: Array.isArray(body.candidates) ? body.candidates : [],
    metadata: {
      source: body.source || 'webhook',
      received_at: new Date().toISOString()
    }
  }
}];

return [{
  json: {
    error: 'missing_jd_data',
    message: 'raw JD text is required in jd_text/raw_jd_text/job_description',
    request_id: $json.request_id || null
  }
}];

function safeParse(text) {
  if (!text || typeof text !== 'string') return null;
  const cleaned = text.replace(/```json|```/gi, '').trim();
  try { return JSON.parse(cleaned); } catch {}
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch {}
  }
  return null;
}

function fallbackJd(raw) {
  const text = String(raw || '').toLowerCase();
  const skillDict = [
    'python','java','javascript','typescript','node.js','react','aws','gcp','azure','docker','kubernetes','sql','nosql','llm','nlp','machine learning','fastapi','spring','microservices','rest api'
  ];
  const found = skillDict.filter((s) => text.includes(s.replace('.js', '')) || text.includes(s));
  const uniq = [...new Set(found)].slice(0, 12);
  const roles = [];
  if (text.includes('engineer')) roles.push('Engineer');
  if (text.includes('developer')) roles.push('Developer');
  if (text.includes('scientist')) roles.push('Scientist');
  if (!roles.length) roles.push('Software Professional');

  let level = 'mid';
  if (text.includes('principal')) level = 'principal';
  else if (text.includes('lead')) level = 'lead';
  else if (text.includes('senior')) level = 'senior';
  else if (text.includes('junior') || text.includes('entry')) level = 'entry';

  const w = uniq.length ? Number((1 / uniq.length).toFixed(4)) : 1;
  const skills = (uniq.length ? uniq : ['communication']).map((name) => ({ name, weight: w }));
  const keywords = uniq.slice(0, 10);

  return { roles, skills, experience_level: level, keywords };
}

const llmRaw = $json.text || $json.output || '';
const parsed = safeParse(llmRaw);
const jd = parsed && Array.isArray(parsed.skills) ? parsed : fallbackJd($json.raw_jd_text);

const valid = Array.isArray(jd.roles) && Array.isArray(jd.skills) && typeof jd.experience_level === 'string' && Array.isArray(jd.keywords);

return [{
  json: {
    request_id: $json.request_id,
    job_id: $json.job_id,
    raw_jd_text: $json.raw_jd_text,
    shortlist_size: $json.shortlist_size,
    weights: $json.weights,
    metadata: $json.metadata,
    supplied_candidates: $json.supplied_candidates,
    jd_contract_valid: valid,
    job_summary: jd
  }
}];

return [{
  json: {
    error: 'jd_schema_validation_failed',
    request_id: $json.request_id,
    job_id: $json.job_id,
    message: 'JD parser could not produce required schema'
  }
}];

function normalizeCandidate(c, idx) {
  const skills = Array.isArray(c.skills) ? c.skills : String(c.skills || '').split(',').map((s) => s.trim()).filter(Boolean);
  return {
    candidate_id: c.candidate_id || `cand-${idx + 1}`,
    name: c.name || `Candidate ${idx + 1}`,
    skills,
    years_experience: Number(c.years_experience || c.exp || 0),
    profile_summary: c.profile_summary || c.summary || '',
    source: c.source || 'input'
  };
}

const provided = Array.isArray($json.supplied_candidates) ? $json.supplied_candidates : [];

const mock = [
  { candidate_id: 'cand-101', name: 'Ava Sharma', skills: ['python','llm','fastapi','docker','aws'], years_experience: 5, profile_summary: 'Built LLM candidate scoring services in production', source: 'mock' },
  { candidate_id: 'cand-102', name: 'Rohan Mehta', skills: ['java','spring','kubernetes','sql'], years_experience: 7, profile_summary: 'Backend platform engineer with hiring pipeline exposure', source: 'mock' },
  { candidate_id: 'cand-103', name: 'Mina Das', skills: ['python','nlp','machine learning','vector db','gcp'], years_experience: 4, profile_summary: 'NLP engineer focused on semantic search', source: 'mock' },
  { candidate_id: 'cand-104', name: 'Ibrahim Khan', skills: ['typescript','node.js','react','rest api'], years_experience: 3, profile_summary: 'Full-stack engineer integrating ATS workflows', source: 'mock' },
  { candidate_id: 'cand-105', name: 'Chen Wu', skills: ['python','microservices','docker','kubernetes','azure'], years_experience: 6, profile_summary: 'Designed cloud-native scoring systems', source: 'mock' }
];

const chosen = provided.length ? provided : mock;
const candidates = chosen.map(normalizeCandidate).filter((c) => c.name);

return [{
  json: {
    request_id: $json.request_id,
    job_id: $json.job_id,
    shortlist_size: $json.shortlist_size,
    weights: $json.weights,
    metadata: $json.metadata,
    job_summary: $json.job_summary,
    candidates,
    candidate_count: candidates.length
  }
}];

return [{
  json: {
    job_summary: $json.job_summary,
    candidates: [],
    warning: 'empty_candidate_pool',
    request_id: $json.request_id,
    job_id: $json.job_id
  }
}];

const out = [];
for (const c of $json.candidates) {
  out.push({
    json: {
      request_id: $json.request_id,
      job_id: $json.job_id,
      shortlist_size: $json.shortlist_size,
      weights: $json.weights,
      job_summary: $json.job_summary,
      candidate: c
    }
  });
}
return out;

const c = $json.candidate || {};
const valid = Boolean(c.name) && Array.isArray(c.skills) && Number.isFinite(Number(c.years_experience));

if (!valid) {
  return [{
    json: {
      ...$json,
      candidate: {
        candidate_id: c.candidate_id || 'unknown',
        name: c.name || 'Unknown',
        skills: Array.isArray(c.skills) ? c.skills : [],
        years_experience: Number(c.years_experience || 0),
        profile_summary: c.profile_summary || ''
      },
      candidate_contract_valid: false
    }
  }];
}

return [{ json: { ...$json, candidate_contract_valid: true } }];

const jdSkills = ($json.job_summary.skills || []).map((s) => String(s.name || '').toLowerCase());
const jdWeight = Object.fromEntries(($json.job_summary.skills || []).map((s) => [String(s.name || '').toLowerCase(), Number(s.weight || 0)]));
const candSkills = ($json.candidate.skills || []).map((s) => String(s).toLowerCase());

let overlap = 0;
let weightHit = 0;
const matched = [];
for (const s of jdSkills) {
  if (candSkills.includes(s)) {
    overlap += 1;
    weightHit += jdWeight[s] || 0;
    matched.push(s);
  }
}

const skillOverlapScore = jdSkills.length ? Math.round((overlap / jdSkills.length) * 100) : 50;
const weightedSkillScore = Math.round(Math.min(weightHit, 1) * 100);

const levelMap = { entry: 1, mid: 2, senior: 3, lead: 4, principal: 5 };
const target = levelMap[$json.job_summary.experience_level] || 2;
const candYears = Number($json.candidate.years_experience || 0);
const candLevel = candYears >= 9 ? 5 : candYears >= 7 ? 4 : candYears >= 4 ? 3 : candYears >= 2 ? 2 : 1;
const expAlignment = Math.max(0, 100 - Math.abs(target - candLevel) * 20);

return [{
  json: {
    ...$json,
    pre_match: {
      skill_overlap_score: Math.round((skillOverlapScore * 0.5) + (weightedSkillScore * 0.5)),
      experience_alignment_score: expAlignment,
      matched_skills: matched,
      missing_skills: jdSkills.filter((s) => !candSkills.includes(s))
    }
  }
}];

