{
  "semantic_similarity": 0-100,
  "why_candidate_matched": "string",
  "missing_skills": ["string"]
}

Job JSON:
{{ JSON.stringify($json.job_summary) }}

Candidate JSON:
{{ JSON.stringify($json.candidate) }}

