  if (m) {
    try { return JSON.parse(m[0]); } catch {}
  }
  return null;
}

const parsed = safeParse($json.text || $json.output || '');
const semantic = parsed && Number.isFinite(Number(parsed.semantic_similarity)) ? Number(parsed.semantic_similarity) : 50;
const pre = $json.pre_match || {};

const skillOverlap = Number(pre.skill_overlap_score || 50);
const expAlign = Number(pre.experience_alignment_score || 50);
const matchScore = Math.round(skillOverlap * 0.45 + expAlign * 0.25 + semantic * 0.30);

const missing = Array.isArray(parsed?.missing_skills) ? parsed.missing_skills : (pre.missing_skills || []);
const explanation = parsed?.why_candidate_matched || `Matched on ${Math.min((pre.matched_skills || []).length, 5)} core skills with ${semantic}% semantic relevance.`;

return [{
  json: {
    ...$json,
    match_result: {
      match_score: Math.max(0, Math.min(100, matchScore)),
      matched_skills: pre.matched_skills || [],
      missing_skills: missing,
      explanation
    },
    match_contract_valid: true
  }
}];

