function safeParse(text) {
  if (!text || typeof text !== 'string') return null;
  const cleaned = text.replace(/```json|```/gi, '').trim();
  try { return JSON.parse(cleaned); } catch {}
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) {
    try { return JSON.parse(m[0]); } catch {}
  }
  return null;
}

const parsed = safeParse($json.text || $json.output || '');
const sentiment = Number(parsed?.sentiment_score ?? 60);
const depth = Number(parsed?.engagement_depth ?? 55);
let interest = Number(parsed?.interest_score ?? Math.round(sentiment * 0.6 + depth * 0.4));
interest = Math.max(0, Math.min(100, interest));

let intent = parsed?.intent_class;
if (!intent) {
  intent = interest >= 75 ? 'high_interest' : interest >= 55 ? 'medium_interest' : interest >= 35 ? 'low_interest' : 'not_interested';
}

const conversationSummary = $json.conversation_summary || 'Candidate showed moderate interest with follow-up questions.';

return [{
  json: {
    ...$json,
    engagement_result: {
      interest_score: interest,
      sentiment_score: sentiment,
      intent_class: intent,
      engagement_depth: depth,
      conversation_summary: conversationSummary
    },
    engagement_contract_valid: true
  }
}];

const matchWeight = Number($json.weights?.match_weight ?? 0.7);
const interestWeight = Number($json.weights?.interest_weight ?? 0.3);
const matchScore = Number($json.match_result?.match_score ?? 0);
const interestScore = Number($json.engagement_result?.interest_score ?? 0);

const final = Math.round((matchScore * matchWeight) + (interestScore * interestWeight));

return [{
  json: {
    request_id: $json.request_id,
    job_id: $json.job_id,
    shortlist_size: $json.shortlist_size,
    job_summary: $json.job_summary,
    candidate: {
      name: $json.candidate.name,
      match_score: Math.max(0, Math.min(100, matchScore)),
      interest_score: Math.max(0, Math.min(100, interestScore)),
      final_score: Math.max(0, Math.min(100, final)),
      explanation: $json.match_result?.explanation || 'Match computed from skills, experience, and semantic relevance.',
      conversation_summary: $json.engagement_result?.conversation_summary || 'No conversation summary available.'
    }
  }
}];

const items = $input.all().map((i) => i.json);
if (!items.length) {
  return [{ json: { job_summary: {}, candidates: [] } }];
}

items.sort((a, b) => b.candidate.final_score - a.candidate.final_score);
const topN = Math.max(1, Number(items[0].shortlist_size || 10));
const candidates = items.slice(0, topN).map((i) => i.candidate);

return [{
  json: {
    job_summary: items[0].job_summary,
    candidates
  }
}];
